parts=[]
toc=[]
def section(id,title,text):
    toc.append((id,title)); parts.append(f'<section id="{id}"><h2>{title}</h2>{text}</section>')
def p(text): return '<p>'+text+'</p>'
def table(headers, rows):
    return '<div class="table"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def ul(items): return '<ul>'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'

section('scope','01 Project direction and scope',p('<strong>CivicSubmittal</strong> is an applicant-side construction permit coordination concept in the logistics and knowledge sector. Its first commercial hypothesis is supervised packet-readiness review for one municipality and one repeatable commercial tenant-improvement workflow. The buyer is a builder operations director or expediting-firm principal; the daily user is a permit coordinator. Licensed architects retain professional decisions; city officials retain permitting decisions.')+p('This deliverable specifies the complete website and isolated synthetic demo. It is an information architecture and design plan, not a built website or production permitting product. The requested $100,000 sale ambition is treated as a craftsmanship and business ambition, not a verified valuation, SaaS price, budget or revenue claim.')+p('The latest direct request governs: use CivicSubmittal, preserve every substantive brief requirement, and apply the uploaded master guide as the website quality and completeness standard. The guide itself says briefs take precedence; your direct instruction reverses that document-level default. Its full website architecture is retained, while factual stage labels and professional boundaries remain accurate. The brief’s earlier “spec only” and later prototype instructions are reconciled here as a specification for a future concept website and demo.')+p('Permit Waypoint and permitwaypoint.com are legacy brief references, not the chosen brand or an approved domain. The historical RDAP 404, unpurchased-domain status and absent trademark clearance are preserved as legacy research notes only. No present availability or legal clearance is inferred. No video or source screenshot was supplied in this chat; the referenced screenshots/43-website-preview.png cannot be treated as inspected evidence.')+table(['Status','Meaning in this plan'],[
('Supplied facts','Company name, audience, five offers, pilot hypotheses, scope limits and validation goals come from your request.'),
('Research','External examples and official source inventory inform positioning; they do not certify local requirements.'),
('Proposed design','Brand territory, page routes, copy, motion timings and sample UI are recommendations for execution.'),
('Synthetic records','All demo projects, addresses, people, comments, timestamps and metrics are fictional.'),
('Unresolved','Initial municipality, exact permit category, rule verifier, source effective dates, legal responsibility, insurer requirements, real forms/auth and approved business details.')]))

section('references','02 Visual and scrolling references',p('Live browser inspection on 27 October 2026 covered Linear’s homepage, Mercury’s homepage, and Ramp’s homepage and corporate-card product hero. Scroll positions were compared visually. This is a focused reference study, not an audit of every page or mobile behavior on those sites. Animation timing, easing, hover behavior and trigger mechanisms not directly tested are not asserted as observations.')+table(['Reference','Observed or documented','CivicSubmittal adaptation'],[
('<a href="https://linear.app/">Linear homepage</a>','Observed: near-black canvas, oversized left-aligned heading, broad detailed workbench, persistent top navigation while scrolling, followed by an editorial statement and fine-line dimensional illustrations.','Borrow readable product density, figure labels and precise linework for the demo. Use warm light surfaces as the main brand environment; reserve dark space for dependency storytelling.'),
('<a href="https://mercury.com/">Mercury homepage</a>','Observed: full-bleed landscape with a desk and laptop, centered headline and actions; after scrolling, a close laptop view occupies the viewport and navigation changes to a dark surface. The page exposes separate feature illustrations and demo entry. The exact scroll-versus-playback mechanism was not isolated.','Connect architectural atmosphere to a concrete workbench: a commercial interior becomes an original drawing and then a packet review. Avoid copying the landscape scene or financial claims.'),
('<a href="https://ramp.com/">Ramp homepage</a>','Observed: light background, subtle dot field, high-contrast accent actions, generous headline spacing, detailed product visual and a portfolio chapter with individually linked product panels.','Give all five offers clear names, distinct visual responsibilities and routes. Use evidence and scope in place of counters, customer logos or borrowed proof.'),
('<a href="https://ramp.com/corporate-cards">Ramp product page</a>','Observed: centered product-specific hero, physical product object, separate demo action. Page content develops controls, workflows, related products and FAQs.','Give each module its own hero object and detailed workflow; maintain the same navigation and typography system.'),
('<a href="https://gsap.com/blog/3-8/">GSAP horizontal container animation</a>','Official documented example: vertical scrolling moves a pinned horizontal container and triggers animations inside its panels. This is a documented implementation reference, not an observed animation on Linear or Mercury.','Use one bounded horizontal approval-dependency chapter, with explicit progress, a skip link and a vertical mobile equivalent.'),
('<a href="https://gsap.com/scroll/">GSAP scroll examples</a>','Official examples demonstrate scrubbed animation, drawing and pinning.','Use reversible source connectors and a vertically progressing deficiency story; animation reveals cause and responsibility.')])+p('<strong>Reference synthesis:</strong> Mercury supplies scene-to-product atmosphere; Linear supplies evidence hierarchy; Ramp supplies product-suite coverage; GSAP supplies explicit horizontal and vertical interaction mechanics. All proposed hover treatments below are CivicSubmittal designs, not claims that these references use them.'))

section('brand','03 Three visual territories and recommended identity',table(['Territory','Composition and materials','Motion and suitability'],[
('A — Civic Atlas · recommended','Warm limestone and paper, oxblood accents, editorial serif headings, precise sans-serif UI, annotated parcel lines and translucent drawing sheets.','A parcel resolves into a dependency chain, then a reviewed packet. Best fit for an architectural, premium, evidence-led company.'),
('B — Permit Workroom','Bright gallery space, graphite type, terracotta accents, original commercial-interior photography and an architect’s drawing table.','Camera-like crops move from a room to its drawings and annotations. More human and service-led; fewer map-led compositions.'),
('C — Coordination Instrument','Pale mineral surfaces, dark technical panels, olive accents, compact typographic labels, schedule rails and operational queues.','Dependencies align into calendar lanes and reviewer tasks. Stronger operations-software emphasis; less editorial luxury.')])+p('Proceeding recommendation: <strong>Civic Atlas</strong>. Character: precise, calm, accountable, architectural, quietly ambitious. The signature object is a translucent permit packet anchored to an address and a source trail. The same object changes role across pages without repeating the same composition.')+table(['Brand element','Specification'],[
('Logo and favicon concept','An open C built from two offset plan-sheet corners and one small registration point. Pair with a custom-spaced CivicSubmittal wordmark. No crest, municipal seal, checkmark stamp or government insignia. Produce original vector primary/reverse/monochrome marks, compact lockup and 16/32px legibility checks before high-fidelity design.'),
('Proposed palette','Paper #F6F3EC; white #FFFFFF; ink #242824; muted #62685F; oxblood #713A46; limestone #E5DFD3; deep forest #253C33. Error #A63832; warning #825B16; reviewed #2D684E; focus #713A46. Test actual text/background pairs before approval.'),
('Typography direction','Editorial display serif with moderate contrast; humanist sans for copy and forms; mono for source IDs and dates. Candidate pairing: Instrument Serif, Manrope, IBM Plex Mono. This is a proposed pairing; verify font files, licenses, weights and rendering before use. Never use a delicate serif for tiny operational text.'),
('Type and layout','Desktop H1 72–88px, mobile 40–48px; H2 44–56px / 30–36px; body 18px / 16px; UI 14–16px. Reading measure 60–70 characters. Content 1200px; visual canvas up to 1440px; desktop gutter 48–64px, mobile 20px. Spacing scale 4/8/12/16/24/32/48/64/96/128.'),
('Materials and images','Original commercial interiors with warm daylight; schematic parcel maps; thin-rule grids; frosted tracing paper; close drawing crops. No stock construction handshake, random skyline, gratuitous blue gradients, glowing orb or decorative map implying live coverage.'),
('Icons and finish','Consistent 1.5–2px stroke icons. Diagram arrows terminate at ports, route around labels and distinguish sequential from parallel edges. Quiet 1px borders and shallow shadows; 8–12px component corners, not universal pill cards.'),
('Asset pack to produce next','Logo/favicons, social card, original architectural hero image, schematic jurisdiction map, dependency SVG, original sample drawing, annotation layers, packet preview, source card, comment matrix, calendar lanes, illustrative benchmark chart and mobile crops.')]))

section('positioning','04 Positioning and content hierarchy',p('<strong>Hero headline:</strong> Know what your next submission is missing.')+p('<strong>Supporting copy:</strong> Explore a proposed applicant workspace for checking permit packets against cited local requirements, resolving deficiencies with your architect, and preparing for human submission. Starting with one municipality and one repeatable tenant-improvement workflow.')+p('<strong>Tagline retained:</strong> An applicant-side packet readiness map for one jurisdiction and one repeatable permit type.')+p('<strong>Vision:</strong> Project teams understand the authority, drawings and predecessor approvals governing the next submission before rework occurs. <strong>Mission:</strong> Translate cited local requirements into supervised checklists and reviewer-response tracking, without standing in for the authority having jurisdiction.')+p('Primary CTA: <strong>Discuss a packet-review pilot</strong>. Secondary CTA: <strong>Explore the synthetic demo</strong>. On a validated jurisdiction page, the pilot CTA can say “Request a review for an upcoming packet.” Never use “Get approved,” “Instant permit,” or an implied municipal endorsement.')+p('Use a discreet persistent “Research-stage concept” status on marketing pages. Every product preview carries “CONCEPT PREVIEW” and “DEMO — SYNTHETIC DATA.” Proposed module labels appear next to product names, and test prices carry their hypothesis qualifier beside the number.'))

modules=[
('Permit Desk','/products/permit-desk','Address/project-specific authority and permit dependency map','Schematic boundary map with unsupported-zone hatching','Address + project type → authority questions → predecessor/parallel dependencies → source-linked map','A dependency brief for human verification; unverified boundary blocks readiness.'),
('Permit Review','/products/permit-review','Submission-ready document and drawing checklist QA; first pilot','Exploded drawing packet with missing-sheet annotation','Synthetic packet → applicable checklist → missing or mismatched item → architect correction → human readiness check','A reviewed packet checklist and exception summary; not a permit or code-compliance certification.'),
('Permit Proof','/products/permit-proof','Reviewer-comment classifier and response tracker','Comment on the left, linked response and drawing revision on the right','Comment → suggested category → evidence → proposed response → assigned architect → human review','A response matrix; ambiguous classifications remain unresolved rather than auto-sent.'),
('Permit Signal','/products/permit-signal','Interagency dependency and calendar dashboard','Parallel lanes with predecessor connectors and dated owner actions','Dependency → owner → next check → conflict → revised applicant schedule','A coordination schedule; dates are planned checks, not promised city review deadlines.'),
('Permit Report','/products/permit-report','Portfolio permit-cycle benchmarking and bottleneck analysis','Illustrative cohort chart with sample-size and missing-data labels','Consented history → comparable city/type cohort → cycle/rework breakdown → bottleneck review','An illustrative report initially; no measured ROI or broad cross-city comparison without verified data.')]
section('products','05 Complete product inventory',p('Public naming: <strong>CivicSubmittal Permit Desk, Permit Review, Permit Proof, Permit Signal and Permit Report.</strong> This replaces the legacy Permit Waypoint prefix while preserving all five working feature-line names and responsibilities. Each is a separate proposed paid-offer test, not an already-live plan. Names remain subject to clearance.')+table(['Module and route','Job','Hero object','Workflow','Output and exception'],[(f'<strong>{a}</strong><br><code>{b}</code>',c,d,e,f) for a,b,c,d,e,f in modules])+p('Every module appears on the homepage, in the product menu, on the product portfolio page, on its own page, and as a selectable interest in demo/pilot intake. The first pilot tests Permit Review only; selecting another module records interest without implying availability.'))

