style='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f6f3ec;color:#242824;font:16px/1.65 system-ui,sans-serif}a{color:#713a46;text-underline-offset:4px}header{background:#253c33;color:#f6f3ec;padding:72px max(6vw,24px)}header h1{font:clamp(42px,6vw,76px)/1.07 Georgia,serif;max-width:1000px;margin:18px 0}header p{max-width:830px;color:#e5dfd3}small,.eyebrow{font:12px/1.6 ui-monospace,monospace;letter-spacing:.1em;text-transform:uppercase}.badge{display:inline-block;border:1px solid #819286;border-radius:4px;padding:5px 10px;margin:0 8px 8px 0}main{max-width:1370px;margin:auto;padding:42px 5vw 90px}nav{columns:2;padding:20px 28px;background:#fff;border:1px solid #e5dfd3}nav a{display:block;margin:8px 0;break-inside:avoid}section{padding:48px 0;border-bottom:1px solid #d7d2c7;scroll-margin-top:20px}h2{font:38px/1.18 Georgia,serif;margin:0 0 24px}p,li{max-width:1000px}p{margin:16px 0}li{margin:10px 0}.table{overflow:auto;margin:26px 0;background:#fff;border:1px solid #ded9ce}table{border-collapse:collapse;width:100%;min-width:760px;font-size:14px}th{text-align:left;background:#e5dfd3;font-size:12px;letter-spacing:.04em;text-transform:uppercase}td,th{padding:17px 18px;border-bottom:1px solid #e5dfd3;vertical-align:top}td:first-child{font-weight:600;min-width:140px}code{font-size:12px;overflow-wrap:anywhere;font-weight:400}footer{padding:30px 5vw;background:#253c33;color:#eee}button{padding:12px 20px;border:1px solid #713a46;background:transparent;color:#713a46;border-radius:4px;cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid #713a46;outline-offset:4px}@media(max-width:680px){nav{columns:1}main{padding:24px 20px}header{padding:42px 20px}h2{font-size:30px}section{padding:35px 0}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{header{background:white;color:#242824;padding:10px}header p{color:#242824}nav,button{display:none}main{padding:0}section{break-before:page}table{min-width:0;font-size:10px}td,th{padding:8px}.table{overflow:visible}a{color:inherit}footer{background:white;color:#242824}}'''
def write_report(extra=''):
    nav=''.join(f'<a href="#{i}">{t}</a>' for i,t in toc)
    html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CivicSubmittal website architecture and motion specification</title><style>'+style+'</style></head><body><header><div class="eyebrow">CivicSubmittal · Concept 43 · 27 October 2026</div><h1>Website architecture<br>and motion specification</h1><p>A complete five-product company experience, built around one source-linked packet and the people responsible for its next step.</p><span class="badge">Planning deliverable</span><span class="badge">Research-stage concept</span><span class="badge">No production product built</span></header><main><button onclick="window.print()">Print or save as PDF</button><h2 style="margin-top:36px">Contents</h2><nav>'+nav+'</nav>'+''.join(parts)+extra+'</main><footer>CivicSubmittal · Proposed design and IA · Sources and scope qualifications are included beside the relevant material.</footer></body></html>'
    (root/'CivicSubmittal-Website-Architecture.html').write_text(html)

section('research','18 Official research and citation inventory',p('Perplexity’s high research preset was used for this source study on 27 October 2026. The inventory below identifies authoritative process pages and comparison sources. It does not certify individual local rules, effective dates or project applicability. All item-level effective dates and human verification remain pending unless explicitly established later.')+table(['ID and official source','Finding and design implication','Verification gap'],[
('SRC-01 · <a href="https://www.phila.gov/2026-03-12-how-the-permit-navigator-is-simplifying-philadelphias-permitting-process/">Philadelphia Navigator expansion announcement</a>','The March 12, 2026 announcement describes expanded business/commercial, residential and zoning guidance. CivicSubmittal must test additional packet-level value rather than claim permit discovery is absent.','Announcement date is not a rule effective date. Compare actual chosen workflow with the current navigator.'),
('SRC-02 · <a href="https://www.phila.gov/programs/smartcityphl/permit-navigator/frequently-asked-questions/">Navigator FAQ</a>','The FAQ separates navigation from official permitting and eCLIPSE. The applicant workspace should link out for filing and clearly distinguish advice-like guidance from official decisions.','Check current scope and any data lag for the chosen address/workflow.'),
('SRC-03 · <a href="https://www.phila.gov/programs/smartcityphl/permit-navigator/">Navigator program page</a>','Research found narrower legacy scope language than the 2026 announcement. Preserve this discrepancy as a source-maintenance issue.','Resolve with the live navigator or authority; do not silently treat older exclusions as definitive current coverage.'),
('SRC-04 · <a href="https://www.phila.gov/services/permits-violations-licenses/apply-for-a-permit/building-and-repair-permits/get-a-building-permit/">Philadelphia Building Permit</a>','Official overview covers alterations and conditional documents/reviews. Use applicability questions and project-dependent requirements rather than a universal checklist.','Extract exact source sections and triggers with a qualified verifier before pilot use. The synthetic life-safety example is not established by this citation.'),
('SRC-05 · <a href="https://www.phila.gov/services/permits-violations-licenses/apply-for-a-permit/building-and-repair-permits/get-permits-without-plans-ez-permits/">EZ permits without plans</a>','Some work follows an EZ route subject to applicable standards. Scope classification must precede document QA.','Confirm whether the selected TI workflow uses a standard commercial application or a specific EZ route.'),
('SRC-06 · <a href="https://www.phila.gov/departments/department-of-licenses-and-inspections/eclipse-faqs/">eCLIPSE FAQs</a> and <a href="https://eclipse.phila.gov/">official portal</a>','Official submission is an external government process. CivicSubmittal initially provides applicant preparation and a manual handoff.','Validate digital formats, workflow constraints, permissions and current portal behavior; no integration or filing automation is established.'),
('SRC-07 · <a href="https://www2.gov.bc.ca/gov/content/industry/natural-resource-use/natural-resource-permits/permit-connect-bc">BC Permit Connect</a>','A navigation service for provincial natural-resource authorizations, including housing and electrification, provides a coordination precedent. It is not evidence of universal municipal tenant-improvement coverage.','BC is a comparator only, not CivicSubmittal coverage or the selected launch market.'),
('SRC-08 · <a href="https://opengov.com/products/permitting-and-licensing/">OpenGov Permitting and Licensing</a>','Government-side permitting software includes applicant-facing workflows. Compare system responsibilities fairly; CivicSubmittal is a proposed applicant-side preparation layer.','Vendor capabilities are vendor claims. No CivicSubmittal integration, partnership or superiority has been demonstrated.')])+p('The brief assesses evidence as high for fragmentation/substitutes and low for buyer budget. The official sources establish available processes and alternatives; they do not establish willingness to pay CivicSubmittal. The pilot must test the exact unmet need, acceptable responsibility model and sustainable rule-maintenance cost.')+p('Additional motion reference: <a href="https://codepen.io/GreenSock/pen/WNjaxKp">GreenSock horizontal containerAnimation demonstration</a>. This provides a concrete four-panel interaction mechanism to adapt, not a visual identity to copy.'))

if __name__=='__main__': write_report()
